import{_ as a,o as t,c as o,a7 as r}from"./chunks/framework.FWlv_suP.js";const u=JSON.parse('{"title":"MetroPocket Data Collection","description":"Official Data Collection for MetroPocket.","frontmatter":{"title":"MetroPocket Data Collection","description":"Official Data Collection for MetroPocket.","navbar":false,"sidebar":false,"aside":false,"outline":false,"footer":false,"prev":false,"next":false,"editLink":false,"lastUpdated":false,"pageClass":"standalone-policy"},"headers":[],"relativePath":"data-collection/metro-pocket.md","filePath":"data-collection/metro-pocket.md"}'),s={name:"data-collection/metro-pocket.md"};function n(c,e,l,i,d,p){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="metropocket-data-collection" tabindex="-1">MetroPocket Data Collection <a class="header-anchor" href="#metropocket-data-collection" aria-label="Permalink to &quot;MetroPocket Data Collection&quot;">​</a></h1><p><strong>Last reviewed:</strong> October 14, 2026</p><h2 id="on-device-data" tabindex="-1">On-device data <a class="header-anchor" href="#on-device-data" aria-label="Permalink to &quot;On-device data&quot;">​</a></h2><p>MetroPocket stores installed metro and TV data packs, pack metadata, a theme preference, and any saved train schedules in local browser/WebView storage. Route planning, station searches, TV channel lookups, and train schedule searches are processed on the device. The web app may cache its files for offline use. It does not request GPS/location, contacts, camera, microphone, phone-state, notifications, or broad storage access.</p><p>On Web/PWA, a user can choose a CSV file to create one saved train schedule. On Web/PWA and Android, a user can choose a local Train backup database to restore or choose a destination for an exported backup. These files are processed locally. MetroPocket does not upload CSV content, train schedules, or backup bytes to a server.</p><h2 id="network-requests" tabindex="-1">Network requests <a class="header-anchor" href="#network-requests" aria-label="Permalink to &quot;Network requests&quot;">​</a></h2><p>When you open <strong>Offline Data</strong>, the app requests a public manifest to check pack availability and updates. It downloads a pack only after you choose to install one. The web app also loads its files from its hosting service. The developer does not receive your selected route, station, search, or channel lookup as part of these requests. Hosting providers can process ordinary network connection data under their own policies.</p><h2 id="data-received-by-the-developer" tabindex="-1">Data received by the developer <a class="header-anchor" href="#data-received-by-the-developer" aria-label="Permalink to &quot;Data received by the developer&quot;">​</a></h2><p>MetroPocket has no account, ads, developer-operated analytics, tracking SDK, or developer-operated cloud database. The developer does not receive locally stored packs, route choices, channel lookups, train schedules, or backups. If you contact support, the developer receives only the information you send in your email.</p><h2 id="google-play-data-safety-context" tabindex="-1">Google Play Data safety context <a class="header-anchor" href="#google-play-data-safety-context" aria-label="Permalink to &quot;Google Play Data safety context&quot;">​</a></h2><p>This describes the current app behavior, not a permanent Play Console declaration. Review the actual shipped app and every release before submitting or updating Google Play Data safety answers.</p>',11)])])}const f=a(s,[["render",n]]);export{u as __pageData,f as default};
